  vec2 uv = vUv;
  float rad = vRadius;

uvc = (vUv-0.5) * uAspect.xy + 0.5 -centre;
omask = clamp01(15*(0.55-uvc.y));
uv2 = project (uvc) * vec2(1,1.5);
vec2 ring = (texture(sampler_noise_mq,-uTime/16+length(uv2)/2)-0.5).xy*sat(1-length(uv2));
vUv += ring.xy *(1-omask)*.02;

